"""Alembic environment. Migrations are hand-written SQL (frozen), not autogenerated."""

from __future__ import annotations

import os

from alembic import context
from sqlalchemy import create_engine

url = context.config.attributes.get("url") or os.environ.get("AETHER_DATABASE_URL")
if not url:
    # Same source as the app: AETHER_* variables or apps/api/.env (docs/LOCAL-DEV.md).
    from aether.settings import Settings

    url = Settings().database_url
if not url:
    raise RuntimeError("AETHER_DATABASE_URL is not set")


def run() -> None:
    if context.is_offline_mode():
        context.configure(url=url, literal_binds=True)
        with context.begin_transaction():
            context.run_migrations()
        return
    engine = create_engine(url)
    with engine.connect() as conn:
        context.configure(connection=conn)
        with context.begin_transaction():
            context.run_migrations()


run()
